<template>
  <CampaignForm
    v-if="campaign"
    :initial-values="processedPassedData"
    :urgency-presets="settingsData?.urgency_presets"
    :throttling="settingsData?.throttling"
    :channel-message-cost="settingsData?.channel_message_cost"
    :validation-schema="formSchema"
    :is-saving="isUpdateCampaignLoading"
    submit-label="Save Changes"
    guard-unsaved-changes
    disable-submit-when-pristine
    :on-submit="onSubmit"
  />
</template>

<script setup lang="ts">
import {
  getAllSystemSettings,
  type GetAllSystemSettingsResponse,
  type GetCampaignDetailsResponse,
  type CampaignUpdateRequest,
} from '~/client';
import { formSchema } from '~/constants/validationSchemas/campaignUpdate';
import { useUpdateCampaign } from '~/mutations/recruitment/updateCampaign';
import type { CampaignFormValues } from '~/components/recruitment/CampaignForm.vue';

const props = defineProps<{
  campaign?: GetCampaignDetailsResponse;
}>();

definePageMeta({
  roles: ['admin'],
  skipNavJourney: true,
});

const campaignId = computed(() => useRoute('recruitment-campaigns-id-edit').params.id);

useHead({
  title: () => (props.campaign?.name ? `Edit ${props.campaign.name}` : 'Edit Campaign'),
});

const { data: settingsData } = useQuery({
  key: () => ['system-settings'],
  query: (): Promise<GetAllSystemSettingsResponse> => getAllSystemSettings({ composable: '$fetch' }),
});

const { updateCampaign, isUpdateCampaignLoading } = useUpdateCampaign();

const processedPassedData = computed<CampaignFormValues>(() => ({
  name: props.campaign?.name,
  urgency_level: props.campaign?.urgency_level,
  channel_strategy: props.campaign?.channel_strategy,
  selling_points: props.campaign?.selling_points,
  latest_news: props.campaign?.latest_news,
  custom_notes: props.campaign?.custom_notes,
  end_date: props.campaign?.end_date ?? null,
  target_application_count: props.campaign?.target_application_count ?? null,
  target_assignment_count: props.campaign?.target_assignment_count ?? null,
}));

const onSubmit = async (formValues: CampaignFormValues) => {
  if (!props.campaign) return;
  await updateCampaign({
    campaignId: props.campaign.id,
    data: formValues as CampaignUpdateRequest,
  }).then(() => navigateTo({ name: 'recruitment-campaigns-id', params: { id: campaignId.value } }));
};
</script>
