import { updateCampaign } from '~/client';
import type { UpdateCampaignResponse, CampaignUpdateRequest } from '~/client';

export const useUpdateCampaign = defineMutation(() => {
  const queryCache = useQueryCache();
  const { mutateAsync, asyncStatus } = useMutation({
    mutation: (params: { data: CampaignUpdateRequest; campaignId: string }): Promise<UpdateCampaignResponse> =>
      updateCampaign({
        composable: '$fetch',
        path: { campaign_id: params.campaignId },
        body: ref(params.data),
      }),
    onSuccess: (_, params) => {
      queryCache.invalidateQueries({ key: ['recruitment-campaign', params.campaignId] });
      queryCache.invalidateQueries({ key: ['recruitment-campaigns.list'] });
      queryCache.invalidateQueries({ key: ['recruitment-campaigns.selector'] });
      showToastSuccess('Campaign updated successfully');
    },
    onError: (error) => {
      showToastError(error);
    },
  });

  return {
    updateCampaign: mutateAsync,
    isUpdateCampaignLoading: computed(() => asyncStatus.value === 'loading'),
  };
});
